"""Build RE/project_pipeline.html from the checklist and source-cited roadmap.

Run from the private RE repository root: py RE/tools/build_pipeline.py
Edit this generator/template, never the generated project_pipeline.html.
"""
import html, re, subprocess, pathlib, datetime

ROOT = pathlib.Path(__file__).resolve().parents[2]
SRC = ROOT / "RE" / "12_remaining_movement_checklist.md"
OUT = ROOT / "RE" / "project_pipeline.html"

def inline(s):
    s = html.escape(s, quote=False)
    s = re.sub(r"`([^`]+)`", r"<code>\1</code>", s)
    s = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", s)
    s = re.sub(r"~~(.+?)~~", r"<s>\1</s>", s)
    # Only explicit HTTPS and repository-local Markdown source links are emitted.
    s = re.sub(r"\[([^\]]+)\]\((https://[^\s)]+|[A-Za-z0-9_./-]+\.md)\)",
               lambda m: f'<a href="{html.escape(html.unescape(m[2]), quote=True)}">{m[1]}</a>', s)
    return s

# ---------------------------------------------------------------- parse the checklist
lines = SRC.read_text(encoding="utf-8").splitlines()
sections = []  # {title, level, items:[{status, text, children:[...]}], notes:[]}
cur = None
item_stack = []  # (indent, item)
for ln in lines:
    m = re.match(r"^(#{2,3})\s+(.*)", ln)
    if m:
        cur = {"title": m.group(2).strip(), "level": len(m.group(1)), "items": [], "notes": []}
        sections.append(cur)
        item_stack = []
        continue
    if cur is None:
        continue
    m = re.match(r"^(\s*)- (\[(x| |~)\] )?(.*)", ln)
    if m:
        indent = len(m.group(1))
        status = {"x": "done", "~": "partial", " ": "open"}.get(m.group(3)) if m.group(2) else None
        it = {"status": status, "text": m.group(4).strip(), "children": []}
        while item_stack and item_stack[-1][0] >= indent:
            item_stack.pop()
        if item_stack:
            item_stack[-1][1]["children"].append(it)
        else:
            cur["items"].append(it)
        item_stack.append((indent, it))
        continue
    if ln.strip() and item_stack and ln.startswith(" "):
        item_stack[-1][1]["text"] += " " + ln.strip()
        continue
    if ln.strip() and not ln.startswith("---"):
        cur["notes"].append(ln.strip())

def inherit(it, parent_status):
    st = it["status"]
    for c in it["children"]:
        inherit(c, st or parent_status)
    if st is None and it["children"]:
        sts = [c["status"] for c in it["children"] if c["status"]]
        if sts:
            it["status"] = "done" if all(s == "done" for s in sts) else ("open" if all(s == "open" for s in sts) else "partial")

# RE/12's checkmarks record implementation, not acceptance of the integrated build.
# PR #23 merged 2026-10-07 (28a4cba); tested on 2fca4bc, whose tree main 28a4cba matches exactly (RE/15 §6.3).
SMOOTHING_ITEMS = ("**Default-camera target/eye lag", "**Stick-to-ground visual smoothing", "**`ik.rs` running ankle")
SMOOTHING_EVIDENCE = (" Source: [RE/15 §6.3](15_ac1rs_comparison.md); "
                      "[2fca4bc](https://github.com/Banned445/AC1-Movement-Rewritten/commit/2fca4bc); "
                      "[merged PR #23](https://github.com/Banned445/AC1-Movement-Rewritten/pull/23). "
                      "Tested: 248 passed / 0 failed / 21 ignored, release build and rendered step/staircase checks on 2fca4bc; merged main 28a4cba has the identical tree.")

def review_status(it):
    if it["text"].startswith(SMOOTHING_ITEMS):
        it["status"] = "done"
        it["text"] += SMOOTHING_EVIDENCE
    for child in it["children"]:
        review_status(child)

for s in sections:
    number = re.match(r"(\d+(?:\.\d+)*)(?:\.\s|\s)", s["title"])
    s["source"] = f"RE/12 §{number[1]}" if number else f'RE/12 — {s["title"]}'
    for it in s["items"]:
        review_status(it)
        inherit(it, None)

def count(items):
    c = {"done": 0, "partial": 0, "validation": 0, "open": 0}
    for it in items:
        if it["status"] in c and not it["children"]:
            c[it["status"]] += 1
        c2 = count(it["children"])
        for k in c:
            c[k] += c2[k]
    return c

