handoff_html = []
for title, status, blurb, rows in HANDOFF:
    label = "Excluded" if status == "note" else LABEL[status]
    rows_html = "".join(f'<li class="step"><span class="pill {status}">{label}</span><span>{inline(row)}</span></li>' for row in rows)
    handoff_html.append(f'<article class="phase {status}"><h3>{inline(title)}</h3><p>{inline(blurb)}</p><ul>{rows_html}</ul></article>')

def render_item(it, source):
    st = it["status"] or "note"
    text = it["text"]
    # split "headline → detail" when the item carries a status note after the title
    head, detail = text, ""
    m = re.match(r"^(\*\*.+?\*\*[^→]*?)(\s*\*\*→.*|\s*→.*)$", text)
    if m:
        head, detail = m.group(1), m.group(2).strip()
        if detail.startswith("**→") and detail.endswith("**"):
            detail = detail[3:-2].strip()
        detail = re.sub(r"^→\s*", "", detail)
    kids = "".join(render_item(c, source) for c in it["children"])
    tag = f'<span class="pill {st}">{LABEL.get(st, "")}</span>' if st in LABEL else '<span class="pill note">·</span>'
    det = f'<div class="detail">{inline(detail)}</div>' if detail else ""
    sub = f'<ul class="items sub">{kids}</ul>' if kids else ""
    return f'<li class="item" data-status="{st}">{tag}<div class="body"><div class="head">{inline(head)}</div>{det}<div class="source">Source: <a href="12_remaining_movement_checklist.md">{inline(source)}</a></div>{sub}</div></li>'

total = {"done": 0, "partial": 0, "validation": 0, "open": 0}
sec_html = []
for i, s in enumerate(sections):
    if not s["items"] and not s["notes"]:
        continue
    c = count(s["items"])
    for k in c:
        total[k] += c[k]
    n = sum(c.values())
    bar = ""
    if n:
        bar = (f'<div class="bar" role="img" aria-label="{c["done"]} done, {c["partial"]} partly done, {c["validation"]} awaiting validation, {c["open"]} open">'
               f'<span class="seg done" style="flex:{c["done"]}"></span><span class="seg partial" style="flex:{c["partial"]}"></span>'
               f'<span class="seg validation" style="flex:{c["validation"]}"></span><span class="seg open" style="flex:{c["open"]}"></span></div>'
               f'<div class="counts"><span>{c["done"]} done</span><span>{c["partial"]} partly</span><span>{c["validation"]} test</span><span>{c["open"]} open</span></div>')
    notes = "".join(f"<p>{inline(x)}</p>" for x in s["notes"] if not x.startswith("|"))
    items = "".join(render_item(it, s["source"]) for it in s["items"])
    cls = "sec sub" if s["level"] == 3 else "sec"
    sec_html.append(
        f'<section class="{cls}" id="s{i}"><details open><summary><h3>{inline(s["title"])}</h3>{bar}</summary>'
        f'{"<div class=notes>" + notes + "</div>" if notes else ""}<ul class="items">{items}</ul></details></section>')

